package org.sleepwell.app;

import android.content.ContentValues;
import android.net.Uri;
import java.util.*;

/** Original v1 ordinary-clock alarm contract; hidden behavior fields are never caller JSON. */
public final class AlarmContentContract {
    public static final String AUTHORITY="org.sleepwell.app.alarms";
    public static final Uri ALARMS=Uri.parse("content://"+AUTHORITY+"/shared/v1/alarms");
    public static final String READ="org.sleepwell.app.permission.READ_MANAGED_ALARMS",WRITE="org.sleepwell.app.permission.MANAGE_ALARMS";
    public static final String[] COLUMNS={"_id","revision","hour","minute","days_mask","label","enabled","vibrate","kind","writable","write_issue","next_deadline_ms","scheduling_status"};
    private static final Set<String> NAMES=Set.of(COLUMNS),OPTIONAL_COLUMNS=Set.of("snooze_minutes","smart_window_minutes","smart_sensitivity","smart_respect_goal"),FIELDS=Set.of("hour","minute","days_mask","label","enabled","vibrate","snooze_minutes","smart_window_minutes","smart_sensitivity","smart_respect_goal");
    static final class Request {final int id,limit,before;final String operation,request,match;Request(int id,int limit,int before,String operation,String request,String match){this.id=id;this.limit=limit;this.before=before;this.operation=operation;this.request=request;this.match=match;}}
    static Request parse(Uri uri,String operation){if(uri==null||!"content".equals(uri.getScheme())||!AUTHORITY.equals(uri.getEncodedAuthority())||uri.getFragment()!=null||uri.toString().length()>512)throw new IllegalArgumentException("Use the SleepWell shared/v1/alarms URI.");String path=uri.getEncodedPath();int id=0;if(!"/shared/v1/alarms".equals(path)){String prefix="/shared/v1/alarms/";if(path==null||!path.startsWith(prefix))throw new IllegalArgumentException("Unsupported alarm path.");id=number(path.substring(prefix.length()),Integer.MAX_VALUE);}Set<String> keys=uri.getQueryParameterNames();Set<String> allowed=operation.equals("query")?Set.of("limit","before_id"):operation.equals("insert")?Set.of("request_id"):Set.of("request_id","if_match");if(!allowed.containsAll(keys))throw new IllegalArgumentException("Unsupported alarm query parameter.");for(String key:keys)if(uri.getQueryParameters(key).size()!=1)throw new IllegalArgumentException("Duplicate parameter.");if(operation.equals("query")){if(id>0&&!keys.isEmpty())throw new IllegalArgumentException("Individual alarm queries have no parameters.");return new Request(id,keys.contains("limit")?number(uri.getQueryParameter("limit"),25):10,keys.contains("before_id")?number(uri.getQueryParameter("before_id"),Integer.MAX_VALUE):0,operation,"","");}if(operation.equals("insert")?id!=0:id==0)throw new IllegalArgumentException("Create uses the collection; update/delete require one alarm ID.");String request=uri.getQueryParameter("request_id"),match=uri.getQueryParameter("if_match");if(!BackupRuntime.nonce(request)||!operation.equals("insert")&&(match==null||!match.matches("[0-9a-f]{64}")))throw new IllegalArgumentException("Use a canonical UUID request_id and the current revision as if_match for update/delete.");return new Request(id,1,0,operation,request,match==null?"":match);}
    private static int number(String text,int max){if(text==null||!text.matches("[1-9][0-9]{0,9}"))throw new IllegalArgumentException("Use a canonical positive decimal number.");try{long n=Long.parseLong(text);if(n>max)throw new IllegalArgumentException("Number is out of range.");return (int)n;}catch(NumberFormatException invalid){throw new IllegalArgumentException("Number is out of range.");}}
    static String[] projection(String[] wanted){if(wanted==null)return COLUMNS.clone();if(wanted.length<1||wanted.length>COLUMNS.length+OPTIONAL_COLUMNS.size())throw new IllegalArgumentException("Choose supported alarm columns.");Set<String> seen=new HashSet<>();for(String key:wanted)if(key==null||(!NAMES.contains(key)&&!OPTIONAL_COLUMNS.contains(key))||!seen.add(key))throw new IllegalArgumentException("Unknown or duplicate alarm column.");return wanted.clone();}
    static ContentValues fields(ContentValues input,boolean create){if(input==null||input.size()<1||input.size()>FIELDS.size()||!FIELDS.containsAll(input.keySet()))throw new IllegalArgumentException("Use only documented alarm fields.");ContentValues out=new ContentValues();for(String key:input.keySet()){Object value=input.get(key);if(key.equals("label")){if(!(value instanceof String text)||text.isBlank()||text.length()>80||text.matches("(?s).*[\\p{Cc}\\p{Cf}\\p{Zl}\\p{Zp}].*"))throw new IllegalArgumentException("Use a plain nonempty label of at most 80 characters.");out.put(key,text);}else if(key.equals("enabled")||key.equals("vibrate")){if(value instanceof Boolean flag)out.put(key,flag);else if(value instanceof Integer number&&(number==0||number==1))out.put(key,number==1);else throw new IllegalArgumentException("Use boolean or integer 0/1 for enabled/vibrate.");}else{if(key.equals("smart_window_minutes")||key.equals("smart_sensitivity")||key.equals("smart_respect_goal")){int min=key.equals("smart_window_minutes")?0:-1,max=key.equals("smart_window_minutes")?60:key.equals("smart_sensitivity")?2:1;out.put(key,integer(value,key,min,max));continue;}if(key.equals("snooze_minutes")){if(!(value instanceof Integer)&&!(value instanceof Long)&&!(value instanceof Short)&&!(value instanceof Byte))throw new IllegalArgumentException("Use integer snooze_minutes from 1 to 60.");long minutes=((Number)value).longValue();if(minutes<1||minutes>60)throw new IllegalArgumentException("Use integer snooze_minutes from 1 to 60.");out.put(key,(int)minutes);continue;}if(!(value instanceof Integer)&&!(value instanceof Long)&&!(value instanceof Short)&&!(value instanceof Byte))throw new IllegalArgumentException("Use integer clock/day fields.");long n=((Number)value).longValue();int max=key.equals("hour")?23:key.equals("minute")?59:127;if(n<0||n>max)throw new IllegalArgumentException("Alarm clock/day field is outside its range.");out.put(key,(int)n);}}if(create&&(!out.containsKey("hour")||!out.containsKey("minute")))throw new IllegalArgumentException("Create requires hour and minute.");return out;}
    private static int integer(Object value,String key,int min,int max){if(!(value instanceof Integer)&&!(value instanceof Long)&&!(value instanceof Short)&&!(value instanceof Byte))throw new IllegalArgumentException("Use integer "+key+" from "+min+" to "+max+".");long number=((Number)value).longValue();if(number<min||number>max)throw new IllegalArgumentException("Use integer "+key+" from "+min+" to "+max+".");return (int)number;}
    static void patch(Alarm alarm,ContentValues fields){if(fields.containsKey("hour"))alarm.hour=fields.getAsInteger("hour");if(fields.containsKey("minute"))alarm.minute=fields.getAsInteger("minute");if(fields.containsKey("label"))alarm.label=fields.getAsString("label");if(fields.containsKey("enabled"))alarm.enabled=fields.getAsBoolean("enabled");if(fields.containsKey("vibrate"))alarm.vibrate=fields.getAsBoolean("vibrate");if(fields.containsKey("snooze_minutes"))alarm.snoozeMinutes=fields.getAsInteger("snooze_minutes");if(fields.containsKey("smart_window_minutes"))alarm.smartWindow=fields.getAsInteger("smart_window_minutes");if(fields.containsKey("smart_sensitivity")||fields.containsKey("smart_respect_goal")){if(alarm.smartWakeInvalid||alarm.smartWake==null)throw new IllegalArgumentException("Review saved smart wake-up settings in SleepWell.");alarm.setSmartWake(new AlarmSmartWake(fields.containsKey("smart_sensitivity")?fields.getAsInteger("smart_sensitivity"):alarm.smartWake.sensitivity,fields.containsKey("smart_respect_goal")?fields.getAsInteger("smart_respect_goal"):alarm.smartWake.goal));}if(fields.containsKey("days_mask")){int mask=fields.getAsInteger("days_mask");alarm.days.clear();for(int n=0;n<7;n++)if((mask&(1<<n))!=0)alarm.days.add(n+1);}}
    static int mask(Alarm alarm){int value=0;for(int day:alarm.days){if(day<1||day>7)throw new IllegalArgumentException("Invalid weekday");value|=1<<(day-1);}return value;}
    private AlarmContentContract(){}
}
